function addAltitude() {
  // Agrega 500 pies a la altitud actual
  var DescentRateCalc = SpreadsheetApp.getActive();
  var Hoja1 = DescentRateCalc.getActiveSheet();
  var valorAltitud = Hoja1.getRange(3, 2);
  var valorResultado = Hoja1.getRange(3, 6);

  valorResultado.setValue(valorAltitud + 500);
}
